package main

import "fmt"

type Account struct{ balance int }

// Pointer receiver mutates the real account, so the deposit persists.
func (a *Account) Deposit(amount int) {
	a.balance += amount
}

func main() {
	acct := Account{balance: 100}
	acct.Deposit(50) // Go takes &acct automatically (acct is addressable)
	fmt.Println(acct.balance) // 150
}

