solution.code:
package solution

type Stack struct {
	items []int
}

// Push uses a pointer receiver so the appended element persists.
func (s *Stack) Push(x int) {
	s.items = append(s.items, x)
}

// Pop mutates the slice, so it also needs a pointer receiver.
func (s *Stack) Pop() (x int, ok bool) {
	if len(s.items) == 0 {
		return 0, false // empty: nothing to pop
	}
	top := len(s.items) - 1
	x = s.items[top]
	s.items = s.items[:top] // shrink the slice
	return x, true
}

// Len only reads, so a value receiver is fine.
func (s Stack) Len() int {
	return len(s.items)
}

codeLab.testHarness:
package solution

import "testing"

func TestStack(t *testing.T) {
	var s Stack
	if s.Len() != 0 {
		t.Fatalf("new stack Len=%d want 0", s.Len())
	}
	if _, ok := s.Pop(); ok {
		t.Fatalf("Pop on empty returned ok=true")
	}
	s.Push(1)
	s.Push(2)
	s.Push(3)
	if s.Len() != 3 {
		t.Fatalf("Len=%d want 3", s.Len())
	}
	if x, ok := s.Pop(); !ok || x != 3 {
		t.Fatalf("Pop=%d,%v want 3,true", x, ok)
	}
	if x, ok := s.Pop(); !ok || x != 2 {
		t.Fatalf("Pop=%d,%v want 2,true", x, ok)
	}
	if s.Len() != 1 {
		t.Fatalf("Len=%d want 1", s.Len())
	}
}

