type Celsius float64
type Fahrenheit float64

// Value receiver: Celsius is tiny and we only read it.
func (c Celsius) ToF() Fahrenheit {
	return Fahrenheit(c*9/5 + 32)
}

// String implements fmt.Stringer for nice formatting.
func (c Celsius) String() string {
	return fmt.Sprintf("%.1f\u00b0C", float64(c))
}

func Convert(c Celsius) string {
	return c.String()
}
